import{_ as l,a0 as p,w as r,s as d,I as s,x as t,a1 as a,A as n,ao as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const E=JSON.parse('{"title":"Neo4j 和圖資料庫起步 | LCTT x X-CMD","titleTemplate":false,"description":"Neo4j 和圖資料庫起步 | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Neo4j 和圖資料庫起步 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Neo4j 和圖資料庫起步 | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20170717 Neo4j and graph databases Getting started","title":"Neo4j 和圖資料庫起步","tag":"201712","desc":""},"relativePath":"201712/20170717 Neo4j and graph databases Getting started.md","filePath":"[post].md"}'),g={name:"201712/20170717 Neo4j and graph databases Getting started.md"};function u(h,e,b,C,m,k){const i=p("Link");return r(),d("div",null,[e[30]||(e[30]=s("h1",{id:"neo4j-和圖資料庫起步",tabindex:"-1"},[t("Neo4j 和圖資料庫起步 "),s("a",{class:"header-anchor",href:"#neo4j-和圖資料庫起步","aria-label":"Permalink to “Neo4j 和圖資料庫起步”"},"​")],-1)),e[31]||(e[31]=s("blockquote",null,[s("p",null,"在這個三篇文章系列中的第二篇中，安裝 Neo4j 並通過網頁客户端來在圖中插入和查詢數據。")],-1)),e[32]||(e[32]=s("p",null,[s("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/LIFE_wavegraph.png?itok=z4pXCf_c",alt:"Neo4j 和圖資料庫: 開始",title:"Neo4j and graph databases: Getting started"})],-1)),s("p",null,[e[2]||(e[2]=t("在本系列的 ",-1)),a(i,{href:"https://linux.cn/article-8728-1.html"},{default:n(()=>[...e[0]||(e[0]=[t("第一篇",-1)])]),_:1}),e[3]||(e[3]=t(" 中，我們介紹了圖資料庫中的一些核心概念。在這篇，我們將安裝 ",-1)),a(i,{href:"https://neo4j.com/"},{default:n(()=>[...e[1]||(e[1]=[t("Neo4j",-1)])]),_:1}),e[4]||(e[4]=t(" 並通過網頁客户端在圖中插入並查詢數據。",-1))]),s("p",null,[e[6]||(e[6]=t("可通過 ",-1)),a(i,{href:"https://neo4j.com/download/community-edition/"},{default:n(()=>[...e[5]||(e[5]=[t("他們的網站",-1)])]),_:1}),e[7]||(e[7]=t(" 下載社區版的 Neo4j！你可以下載 Windows 或 OSX 版來測試，也有各 Linux 發行版對應的版本，還有 Docker 版。",-1))]),s("p",null,[e[9]||(e[9]=t("我會在 Debian 9 (stretch) 上安裝軟件。你可在 ",-1)),a(i,{href:"http://debian.neo4j.org/?_ga=2.172102506.853767004.1499179137-1089522652.1499179137"},{default:n(()=>[...e[8]||(e[8]=[t("這裏",-1)])]),_:1}),e[10]||(e[10]=t(" 查看完整説明。如果你正在使用 Debian 8 (jessie) 或更老的版本，你可以安裝當前的版本，但會出現的一點小問題是 jessie 中並沒有安裝 Neo4j 運行所需要的 Java 8 環境。",-1))]),e[33]||(e[33]=o('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>wget -O - https://debian.neo4j.org/neotechnology.gpg.key | sudo apt-key add - echo &#39;deb https://debian.neo4j.org/repo stable/&#39; | sudo tee /etc/apt/sources.list.d/neo4j.list sudo apt-get update sudo apt-get install neo4j</span></span></code></pre></div><p>在我的系統中，出於某些原因，我創建好 <code>/var/run/neo4j</code> 之後它就可以很輕鬆地開始了。Neo4j 給了一個“最大打開文件數”的警告，但因為是測試環境所以我不太需要關心這個問題。Neo4j 默認只會監聽本機 localhost 上的連接。如果你的機器是 Debian ，那這很好，但是我的不是。我修改了 <code>/etc/neo4j/neo4j.conf</code> ，取消註釋了下面這行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dbms.connectors.default_listen_address=0.0.0.0</span></span></code></pre></div><p>在重啓 Neo4j 之後，我可以通過 7474 端口來訪問服務器的 Neo4j 服務。默認的用户名和密碼是 <code>Neo4j</code> 和 <code>neo4j</code>； 你需要設置一個新密碼，然後會出現初始頁面：</p><p><img src="https://opensource.com/sites/default/files/u128651/article_2_image_1.jpg" alt="Installing Neo4J" title="Installing Neo4J"></p>',5)),s("p",null,[e[12]||(e[12]=t("讓我們在 Neo4j 上創建",-1)),a(i,{href:"https://linux.cn/article-8728-1.html"},{default:n(()=>[...e[11]||(e[11]=[t("上篇文章",-1)])]),_:1}),e[13]||(e[13]=t("中使用過的圖。如下圖：",-1))]),e[34]||(e[34]=o('<p><img src="https://opensource.com/sites/default/files/u128651/article_1_image_2.jpg" alt="Graph database image 2, defining a new type of node" title="Graph database image 2, defining a new type of node"></p><p>類似 MySQL 和其它的資料庫系統，Neo4j 的各類操作也使用一套查詢語句。Cypher，就是 Neo4j 使用的查詢語句，但有一些語法區別需要去學習和注意。<ruby>節點<rt>node</rt></ruby>需要用圓括號表示，而<ruby>關係 <rt>relationship</rt></ruby> 需要放在方括號中。因為這是系統中唯二的數據類型，所以瞭解這些就夠了。</p><p>首先，我們創建所有的節點。你需要將下面內容複製黏貼到瀏覽器頂部區域中，在那裏運行查詢語句。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CREATE (a:Person { name: &#39;Jane Doe&#39;, favorite_color: &#39;purple&#39; }) CREATE (b:Person { name: &#39;John Doe&#39; }) CREATE (c:Person { name: &#39;Mary Smith&#39;, favorite_color: &#39;red&#39;, dob: &#39;1992-11-09&#39; }) CREATE (d:Person { name: &#39;Robert Roe&#39; }) CREATE (e:Person { name: &#39;Rhonda Roe&#39; }) CREATE (f:Person { name: &#39;Ryan Roe&#39; }) CREATE (t:City { name: &#39;Petaluma, CA&#39; }) CREATE (u:City { name: &#39;Cypress, TX&#39; }) CREATE (v:City { name: &#39;Grand Prairie, TX&#39; }) CREATE (w:City { name: &#39;Houston, TX&#39; })</span></span></code></pre></div><p>注意，在標籤前的字符就是變量。這些信息會在出現在各個地方，但我們在這裏並不會用到。但你不能不指定相應信息就盲目創建，所以我們使用它們然後就忽略它們。</p><p>在上面一共創建了 10 個節點和 13 個屬性。想查看它們？ 通過下面語句來匹配查詢所有節點：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>MATCH (n) RETURN n</span></span></code></pre></div><p>這條語句會返回一個可視化的圖。（在應用內，你可以在返回的圖中使用”全屏”按鈕來查看大圖)。你將會看到類似下面的圖像：</p><p><img src="https://opensource.com/sites/default/files/u128651/article_2_image_2.jpg" alt="Visual graph" title="Visual graph"></p><p>添加關係需要一點技巧；你需要連接的節點必須是 “<ruby>在限定範圍內的<rt>in scope</rt></ruby>”，意思連接的節點是在當前查詢語句所限定的範圍內的。我們之前使用的查詢語句範圍太大，所以讓我們找到 John 和 Jane 並讓他們結婚：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>MATCH (a:Person),(b:Person) WHERE a.name=&#39;Jane Doe&#39; AND b.name=&#39;John Doe&#39; CREATE (a)-[r:MARRIAGE {date: &#39;2017-03-04&#39;, place: &#39;Houston, TX&#39;}]-&gt;(b)</span></span></code></pre></div><p>這條語句會創建一個關係並設置兩個屬性。重新運行該 <code>MATCH</code> 語句會顯示那個關係。你可以通過鼠標點擊任意的節點或關係來查看它們的屬性。</p><p>我們來添加其它的關係。比起使用一些列的 <code>MATCH</code> 語句，我會一次性做完並從中 <code>CREATE</code> 創建多個關係。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>MATCH (a:Person),(b:Person),(c:Person),(d:Person),(e:Person),(f:Person),(t:City),(u:City),(v:City),(w:City) WHERE a.name=&#39;Jane Doe&#39; AND b.name=&#39;John Doe&#39; AND c.name=&#39;Mary Smith&#39; AND d.name=&#39;Robert Roe&#39; AND e.name=&#39;Rhonda Roe&#39; AND f.name=&#39;Ryan Roe&#39; AND t.name=&#39;Petaluma, CA&#39; AND u.name=&#39;Cypress, TX&#39; AND v.name=&#39;Grand Prairie, TX&#39; AND w.name=&#39;Houston, TX&#39; CREATE (d)-[m2:MARRIAGE {date: &#39;1990-12-01&#39;, place: &#39;Chicago, IL&#39;}]-&gt;(e) CREATE (a)-[n:CHILD]-&gt;(c) CREATE (d)-[n2:CHILD]-&gt;(f) CREATE (e)-[n3:CHILD]-&gt;(f) CREATE (b)-[n4:STEPCHILD]-&gt;(c) CREATE (a)-[o:BORN_IN]-&gt;(v) CREATE (b)-[o2:BORN_IN]-&gt;(t) CREATE (c)-[p:DATING]-&gt;(f) CREATE (a)-[q:LIVES_IN]-&gt;(u) CREATE (b)-[q1:LIVES_IN]-&gt;(u) CREATE (a)-[r:WORKS_IN]-&gt;(w) CREATE (a)-[s:FRIEND]-&gt;(d) CREATE (a)-[s2:FRIEND]-&gt;(e)</span></span></code></pre></div><p>重新運行該 <code>MATCH</code> 語句，你將會看到下面圖像：</p><p><img src="https://opensource.com/sites/default/files/u128651/article_2_image_3.jpg" alt="Graph after re-querying with MATCH" title="Graph after re-querying with MATCH"></p><p>如果你喜歡，你可以將節點拖拉成像我之前畫的圖的樣子。</p><p>在這個例子中，我們唯一使用的 <code>MATCH</code> 就是 <code>MATCH</code> 所有的東西。下面這個查詢會返回兩個結婚了的夫妻並顯示他們之間的關係：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>MATCH (a)-[b:MARRIAGE]-&gt;(c) RETURN a,b,c</span></span></code></pre></div><p>在一個更復雜的圖中，你可以做更多的細節查詢。（LCTT 譯註：此例子為 Neo4j 自帶例子的）例如，你有關於電影和人的節點，還有像 <code>ACTED IN</code>、<code>DIRECTED</code>、<code>WROTE SCREENPLAY</code> 等屬性的關係，你可以運行下面這個查詢：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>MATCH (p:Person { name: &#39;Mel Gibson&#39; })--m:Movie RETURN m.title</span></span></code></pre></div><p>……上述是查詢和 Mel Gibson 相關的所有影片。但如果你想查詢他演過的所有電影，下面這條語句會更有用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>MATCH (p:Person { name: &#39;Mel Gibson&#39; })-[r:ACTED_IN]-&gt;(m:movie) RETURN m.title,r.role</span></span></code></pre></div>',23)),s("p",null,[e[15]||(e[15]=t("還有更多更炫酷的 Cypher 語句可以使用，但我們就簡單介紹這些。更詳細完整的 Cypher 語句可以在 Neo4j 的",-1)),a(i,{href:"https://neo4j.com/docs/developer-manual/current/cypher/"},{default:n(()=>[...e[14]||(e[14]=[t("官網",-1)])]),_:1}),e[16]||(e[16]=t("上查看, 並且也有很多例子可以練習。",-1))]),e[35]||(e[35]=s("p",null,"在此係列的下篇文章中，我們會通過寫些 Perl 腳本來展示如何在應用中使用圖資料庫。",-1)),e[36]||(e[36]=s("p",null,"（圖片來源 : opensource.com）",-1)),e[37]||(e[37]=s("hr",null,null,-1)),s("p",null,[e[18]||(e[18]=t("via: ",-1)),a(i,{href:"https://opensource.com/article/17/7/neo4j-graph-databases-getting-started"},{default:n(()=>[...e[17]||(e[17]=[t("https://opensource.com/article/17/7/neo4j-graph-databases-getting-started",-1)])]),_:1})]),s("p",null,[e[22]||(e[22]=t("作者：",-1)),a(i,{href:"https://opensource.com/users/druthb"},{default:n(()=>[...e[19]||(e[19]=[t("Ruth Holloway",-1)])]),_:1}),e[23]||(e[23]=t(" 譯者：",-1)),a(i,{href:"https://github.com/happygeorge01"},{default:n(()=>[...e[20]||(e[20]=[t("happygeorge01",-1)])]),_:1}),e[24]||(e[24]=t(" 校對：",-1)),a(i,{href:"https://github.com/wxy"},{default:n(()=>[...e[21]||(e[21]=[t("wxy",-1)])]),_:1})]),s("p",null,[e[27]||(e[27]=t("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[25]||(e[25]=[t("LCTT",-1)])]),_:1}),e[28]||(e[28]=t(" 原創編譯，",-1)),a(i,{href:"https://linux.cn/"},{default:n(()=>[...e[26]||(e[26]=[t("Linux中國",-1)])]),_:1}),e[29]||(e[29]=t(" 榮譽推出",-1))])])}const A=l(g,[["render",u]]);export{E as __pageData,A as default};
